refsection.programlisting:
x = rand(1,10);
y = rand(1,10);
new_x = rand(1,10);
new_y = rand(1,10);
//example 1:
C=[8.    2.     7.    4.;6.    4.5    4.    5.;3.    6.     3.    7.;3.    4.     2.    3.;9.    4.     8.    7.];
[tri,ptr] = constrained_delaunay_2(x,y,C);
cdt2_insert_points(ptr,new_x,new_y);
new_tri = cdt2_get_connectivity(ptr);
cdt2_delete(ptr,"ptr"); // ptr is deleted here and cleared from scilab interpreter.
ptr
//example 2:
[tri1,ptr1] = constrained_delaunay_2(rand(1,10),rand(1,10),[]);
clear ptr1; // ptr is not yet defined in scilab interpreter, but the memory is not freed.
cdt2_delete(); // all pointers of cdt2 will be deleted.
